import {localPath,sitePath} from './deployment.js';
import {toggleMotion} from './motion-preference.js';
import {rooms,routes} from './content.js';
import {translate,getRoute,validateBooking,todayInSochi,filterRooms,makeBookingDraft,buildStaySummary} from './state.js';
import {roomDetails,facilities,venues,stories,extras,events,offers,faq} from './experience.js';
import {photos,photoFallback} from './photos.js';
import {stayServices,barDetails,facilityDetails,rituals,extraStories,dinnerDetails} from './details.js';
import {setupFluid,dissolvePhoto,openSoftMenu,closeSoftMenu,prefersQuiet} from './fluid.js';
import {setupMotion,runIntro,transitionPage,setupFilm,cancelTransition,setupRails} from './motion.js';

const siteBase=document.querySelector('meta[name="site-base"]')?.content||'';
const currentPath=()=>localPath(location.pathname,siteBase);
const storage={get:k=>{try{return localStorage.getItem(k)}catch{return null}},set:(k,v)=>{try{localStorage.setItem(k,v)}catch{}}};
let language=new URLSearchParams(location.search).get('lang')||storage.get('litora-language')||'ru';
let season=new URLSearchParams(location.search).get('season')||storage.get('litora-season')||'summer';
if(!['ru','en'].includes(language))language='ru';if(!['summer','winter'].includes(season))season='summer';
let cleanup=()=>{},roomIndex=0,roomImageIndex=0,lightboxItems=[],lightboxIndex=0,bookingDraft=null;
for(const [id,key] of [['candlelight','bar-candlelight-01'],['gastronomic-evening','dining-bereg-05']]){const event=events.find(e=>e.id===id);if(event&&photos[key])event.photo=key;}
const main=document.querySelector('#main'),menu=document.querySelector('#menu'),lightbox=document.querySelector('#lightbox');
const t=(ru,en)=>language==='en'?en:ru;
function interestLabel(id){const record=[...venues,...facilities,...events,...offers].find(x=>x.id===id)||extras[id];return record?tr(record.name||record.title):t('Индивидуальная программа','A personal itinerary');}
const tr=value=>translate(value,language);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function href(path){const url=new URL(path,location.origin);url.searchParams.set('lang',language);url.searchParams.set('season',season);return sitePath(url.pathname,siteBase)+url.search+url.hash;}
const roll=text=>`<span class="roll"><span>${text}</span><span aria-hidden="true">${text}</span></span>`;
const arrow=`<svg viewBox="0 0 28 28" aria-hidden="true"><path d="M5 14h17M15 7l7 7-7 7"/></svg>`;
const softArrow=`<svg viewBox="0 0 28 28" aria-hidden="true"><path d="M5 14h17M15 7l7 7-7 7"/></svg>`;
const pauseControl=()=>`<button class="gallery-pause" data-gallery-pause aria-pressed="false" aria-label="${t('Приостановить смену фотографий','Pause slideshow')}"><span aria-hidden="true"></span></button>`;
const up=`<svg viewBox="0 0 28 28" aria-hidden="true"><path d="M14 23V5M7 12l7-7 7 7"/></svg>`;
const bird=`<path class="bird-shape" d="M2 29Q14 22 20 23Q9 9 8 2Q25 8 31 22Q45 14 60 8Q58 17 43 28Q38 31 31 30L22 34L15 32Z"/>`;
let birdInstance=0;
const birds=()=>{const id='litora-metal-'+(++birdInstance);const shape=bird.replace('class="bird-shape"',`class="bird-shape" style="fill:url(#${id})"`)+`<path class="bird-feathers" d="M13 8L27 24M17 10L29 24M22 13L31 24M53 12L39 25M49 15L37 26M44 19L35 27M19 28L30 27"/>`;return `<svg viewBox="0 0 180 110" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f4e4b4"/><stop offset=".35" stop-color="#c3a66d"/><stop offset=".6" stop-color="#efdaa2"/><stop offset="1" stop-color="#8c6b40"/></linearGradient></defs><g transform="translate(13 43) scale(.95)"><g class="bird-float">${shape}</g></g><g transform="translate(83 4) scale(.8) rotate(-18 30 20)"><g class="bird-float">${shape}</g></g><g transform="translate(99 70) scale(.8) rotate(12 30 20)"><g class="bird-float">${shape}</g></g></svg>`;};

function link(path,label,cls='text-link'){return `<a class="${cls}" href="${href(path)}">${roll(label)}</a>`;}
const eyebrow=text=>`<span class="eyebrow">${text}</span>`;
function photo(key,{cls='',eager=false,parallax=false,frame='natural'}={}){const p=photos[key]||photos[photoFallback],width=p.width||(key==='masterplan'?1536:1672),height=p.height||(key==='masterplan'?1024:941);return `<figure class="photo ${cls}" style="--photo-aspect:${width}/${height}" data-photo-request="${key}" data-photo-resolved="${photos[key]?key:photoFallback}" ${frame==='natural'?'data-natural':''} ${parallax&&frame==='cover'?'data-parallax':''}><img draggable="false" src="${p.src}" ${p.srcset?`srcset="${p.srcset}" sizes="${frame==='cover'?'(max-width:760px) 180vh, 100vw':cls==='album-photo'?'100vw':'(max-width:760px) 100vw, 90vw'}"`:''} width="${width}" height="${height}" alt="${esc(tr(p.alt))}" loading="${eager?'eager':'lazy'}" decoding="async" ${eager?'fetchpriority="high"':''}></figure>`;}

function photoKeyFor(item){if(item.group==='pools')return item.id==='indoor'?'indoor-v2':`pool-${item.id}-01`;if(item.group==='wellness')return `spa-${item.id}-01`;return item.photo||'masterplan';}
const roomPhotos=id=>Object.keys(photos).filter(k=>k.startsWith(`room-${id}-`));
function roomPhoto(id,index=0){return roomPhotos(id)[index%Math.max(roomPhotos(id).length,1)]||'masterplan';}
function bread(label,parent='/'){return `<nav class="breadcrumbs" aria-label="${t('Путь по сайту','Breadcrumb')}">${link('/','LITORA','')}${parent!=='/'?`<span>/</span>${link(parent,routeName(parent),'')}`:''}<span>/</span><span>${label}</span></nav>`;}
function pageHero(title,kicker,key,description=''){return `<section class="page-hero ${description?'page-hero-editorial':''}">${photo(key,{eager:true,parallax:true,frame:'cover'})}<div class="page-hero-copy">${eyebrow(kicker)}<h1 data-title>${title}</h1>${description?`<p>${description}</p>`:''}</div></section>${bread(routeName(currentPath()))}`;}

function routeName(path){const known={'/':t('Главная','Home'),'/resort':t('Отель','The Resort'),'/resort/territory':t('Карта курорта','Resort Map'),'/rooms':t('Номера и люксы','Rooms & Suites'),'/dining':t('Рестораны','Dining'),'/wellness':'SPA & Wellness','/pools':t('Пять бассейнов','Five Pools'),'/experiences':t('Впечатления','Experiences'),'/events':t('Афиша','What’s On'),'/bars':t('Бары и lounge','Bars & Lounges'),'/celebrations':t('Частные события','Celebrations'),'/gallery':t('Галерея','Gallery'),'/journal':t('Журнал','Journal'),'/offers':t('Предложения','Offers'),'/contacts':t('Контакты','Contact'),'/faq':t('Вопросы и ответы','Questions & Answers'),'/reservation':t('Бронирование','Reservations'),'/privacy':t('Конфиденциальность','Privacy'),'/terms':t('О проекте','About this Project')};if(known[path])return known[path];const id=path.split('/').filter(Boolean).at(-1);const entity=rooms.find(r=>r.id===id)||facilities.find(f=>f.path===path)||venues.find(v=>path==='/dining/'+v.id)||stories.find(s=>path==='/journal/'+s.id)||events.find(e=>path==='/events/'+e.id)||offers.find(o=>path==='/offers/'+o.id)||extras[id];if(entity)return tr(entity.name||entity.title);return routes.find(r=>r.path===path)?.title||'LITORA';}
function nav(){document.querySelector('#header').innerHTML=`<nav class="nav" aria-label="${t('Основная навигация','Main navigation')}"><div class="nav-left"><button class="menu-trigger" data-menu aria-expanded="false" aria-controls="menu"><span class="menu-bars"><i></i><i></i></span><span>${t('МЕНЮ','MENU')}</span></button>${link('/rooms',t('НОМЕРА','STAY'),'nav-link')}${link('/dining',t('РЕСТОРАНЫ','DINE'),'nav-link')}${link('/experiences',t('ВПЕЧАТЛЕНИЯ','EXPERIENCES'),'nav-link')}</div><a class="brand" href="${href('/')}" aria-label="LITORA — ${t('главная','home')}"><img src="/demo/litora/brand/monogram.svg" alt=""></a><div class="nav-right">${link('/reservation',t('ВЫБРАТЬ ДАТЫ','RESERVE'),'nav-link nav-book')}<button class="nav-tool" data-language aria-label="${t('Switch to English','Переключить на русский')}">${language==='ru'?'RU / EN':'EN / RU'}</button><button class="nav-tool nav-season" data-season-toggle aria-label="${t('Сменить сезон','Change season')}">${season==='summer'?t('ЛЕТО','SUMMER'):t('ЗИМА','WINTER')}</button></div></nav>${link('/reservation',t('ВЫБРАТЬ ДАТЫ','RESERVE'),'mobile-book')}`;
menu.innerHTML=`<div class="menu-top"><a class="menu-logo" href="${href('/')}">Litora</a><button class="menu-close" data-menu-close>${t('ЗАКРЫТЬ','CLOSE')} &nbsp; ×</button></div><div class="menu-season">${seasonButtons()}</div><div class="menu-columns"><div class="menu-group">${eyebrow(t('ВАША ЛИТОРА','YOUR LITORA'))}${['/resort','/rooms','/dining','/wellness','/experiences'].map(p=>link(p,routeName(p),'')).join('')}</div><div class="menu-group">${eyebrow(t('НА ТЕРРИТОРИИ','ON THE GROUNDS'))}${['/resort/territory','/pools','/beach','/golf','/fitness','/bars'].map(p=>link(p,p==='/beach'?t('Пляж','Beach'):p==='/golf'?t('Гольф','Golf'):p==='/fitness'?t('Фитнес','Fitness'):routeName(p),'')).join('')}</div><div class="menu-group">${eyebrow(t('ПЛАНИРОВАТЬ','PLAN YOUR STAY'))}${['/reservation','/offers','/events','/celebrations','/journal','/gallery'].map(p=>link(p,routeName(p),'')).join('')}</div></div><div class="menu-small">${['/contacts','/faq','/privacy','/terms'].map(p=>link(p,routeName(p),'')).join('')}<span class="micro">SOCHI · BLACK SEA</span></div>`;}
function footer(){document.querySelector('#footer').innerHTML=`<div class="footer-top"><div class="newsletter">${eyebrow(t('ОСТАВАТЬСЯ НА СВЯЗИ','STAY IN TOUCH'))}<h3>${t('Письма с побережья.','Letters from the coast.')}</h3><p>${t('Сезонные истории, новые меню и вечера у моря. Демонстрация формы подписки для портфолио.','Seasonal stories, new menus and evenings beside the sea. A portfolio newsletter demonstration.')}</p><form id="newsletter"><label class="sr-only" for="newsletter-email">Email</label><input id="newsletter-email" type="email" name="email" placeholder="${t('Ваш e-mail','Your email')}" required autocomplete="email"><button type="submit">${t('ПОДПИСАТЬСЯ','SUBSCRIBE')}</button></form><p class="form-status" aria-live="polite" id="newsletter-status"></p></div><div class="footer-clock"><div><span class="micro">${t('МЕСТНОЕ ВРЕМЯ · СОЧИ','LOCAL TIME · SOCHI')}</span><time class="clock" id="sochi-clock"></time></div><div><span class="micro">${t('КОНЦЕПЦИЯ КУРОРТА','THE RESORT CONCEPT')}</span><span class="clock">365</span><span class="micro">${t('ДНЕЙ У МОРЯ','DAYS BY THE SEA')}</span></div></div></div><div class="footer-links"><div class="footer-column"><h4>DISCOVER</h4>${['/resort','/rooms','/dining','/experiences','/celebrations'].map(p=>link(p,routeName(p),'')).join('')}</div><div class="footer-column"><h4>PLAN</h4>${['/reservation','/offers','/journal','/contacts','/faq'].map(p=>link(p,routeName(p),'')).join('')}</div><div class="footer-concept">${eyebrow('LITORA · SOCHI')}<p>${t('Современная архитектура, субтропический сад и личная линия Чёрного моря. Вымышленный курорт, созданный для портфолио.','Contemporary architecture, subtropical gardens and a private stretch of the Black Sea. A fictional resort created for a portfolio.')}</p></div></div><div class="footer-sign" data-footer-sign><div class="signature" aria-label="Litora">${'Litora'.split('').map(c=>`<span aria-hidden="true">${c}</span>`).join('')}</div><div class="footer-birds">${birds()}</div></div><div class="footer-social">${link('/gallery',t('ФОТОГАЛЕРЕЯ','PHOTO JOURNAL'),'pill')}<button class="back-top" data-top>${t('В НАЧАЛО','BACK TO TOP')}<span class="round">${up}</span></button></div><div class="footer-bottom"><button class="motion-toggle" data-motion-toggle aria-pressed="${prefersQuiet()}">${prefersQuiet()?t('Движение уменьшено','Reduced motion'):t('Уменьшить движение','Reduce motion')}</button><span>© ${new Date().getFullYear()} LITORA. ${t('Концепт для портфолио.','A portfolio concept.')}</span><span>${link('/privacy',t('Конфиденциальность','Privacy'),'')} &nbsp; / &nbsp; ${link('/terms',t('Условия демонстрации','Demonstration terms'),'')}</span></div>`;updateClock();}
function updateClock(){const clock=document.querySelector('#sochi-clock');if(clock)clock.textContent=new Intl.DateTimeFormat(language==='ru'?'ru-RU':'en-GB',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());}
setInterval(updateClock,1000);
function seasonButtons(){return `<div class="seasons" role="group" aria-label="${t('Сезон отдыха','Choose your season')}"><button data-season="summer" aria-pressed="${season==='summer'}"><span class="season-icon" aria-hidden="true">☼</span>SUMMER SEASON</button><button data-season="winter" aria-pressed="${season==='winter'}"><span class="season-icon" aria-hidden="true">❄</span>WINTER SEASON</button></div>`;}
function roomTheatre(){const r=rooms[roomIndex],d=roomDetails[r.id],keys=roomPhotos(r.id);return `<div class="room-stage"><div><div class="room-media-frame">${photo(roomPhoto(r.id,roomImageIndex),{cls:'room-photo'})}</div><div class="rail-controls"><div><button data-room-photo="-1" ${keys.length<2?'disabled':''} aria-label="${t('Предыдущее фото','Previous image')}" class="gallery-arrow is-prev">${softArrow}</button><button data-room-photo="1" ${keys.length<2?'disabled':''} aria-label="${t('Следующее фото','Next image')}" class="gallery-arrow">${softArrow}</button></div>${pauseControl()}<span class="counter">${String(roomImageIndex+1).padStart(2,'0')} <span class="muted">/ ${String(Math.max(keys.length,1)).padStart(2,'0')}</span></span></div></div><div class="room-copy">${eyebrow(t('НОМЕРА И ЛЮКСЫ','ROOMS & SUITES'))}<h3>${tr(r.name)}</h3><p>${tr(d.subtitle)}</p><div class="room-meta"><span>${r.area} ${t('м²','m²')}</span><span>${t('до','up to')} ${r.guests} ${t('гостей','guests')}</span><span>${d.bath} ${t(d.bath===1?'санузел':'санузла',d.bath===1?'bath':'baths')}</span></div><p>${tr(d.text)}</p>${link('/rooms/'+r.id,t('ПОСМОТРЕТЬ НОМЕР','EXPLORE THE ROOM'),'pill')}</div></div>`;}
function diningFilm(){return `<div class="dining-stage"><video data-season-film muted playsinline preload="none" poster="/demo/litora/assets/video-frames/${season}-start.png" aria-label="${season==='summer'?t('Летняя подача блюда на террасе','Summer dining service on the terrace'):t('Зимняя подача соуса','Winter sauce service')}" src="/demo/litora/assets/videos/${season}-serving.mp4"></video><button class="video-control" data-film-toggle aria-pressed="false">${t('ВОСПРОИЗВЕСТИ','PLAY FILM')}</button></div><div class="film-caption"><span>${season==='summer'?t('БЕРЕГ · ЛЕТНЯЯ ТЕРРАСА','BEREG · SUMMER TERRACE'):t('БЕРЕГ · ЗИМНИЙ ВЕЧЕР','BEREG · WINTER EVENING')}</span><span>6 SEC · ${t('СЕЗОННАЯ ПОДАЧА','SEASONAL SERVICE')}</span></div>`;}
function rail(items,id){return `<div class="scroll-rail" id="${id}" tabindex="0" aria-label="${t('Галерея впечатлений','Experience gallery')}">${items.map(item=>`<article class="rail-card"><a class="image-link" href="${href(item.path)}">${photo(item.id==='infinity'?'lifestyle-pool-01':item.photo||photoKeyFor(item))}</a><h3>${tr(item.name)}</h3><p>${tr(item.text)}</p><div class="card-cta">${link(item.path,t('ПОДРОБНЕЕ','EXPLORE'))}</div></article>`).join('')}</div><div class="rail-controls"><div><button data-rail="${id}" data-direction="-1" aria-label="${t('Предыдущий сюжет','Previous scene')}" class="gallery-arrow is-prev">${softArrow}</button><button data-rail="${id}" data-direction="1" aria-label="${t('Следующий сюжет','Next scene')}" class="gallery-arrow">${softArrow}</button></div><span class="rail-meta"><span class="micro" data-rail-status="${id}" aria-live="polite">01 / ${String(items.length).padStart(2,'0')}</span><span class="micro">${t('В ВАШЕМ РИТМЕ','AT YOUR OWN PACE')}</span></span></div>`;}
function closing(){return `<section class="closing stay-planner"><div class="stay-planner-image">${photo('pool-infinity-01')}<span class="micro">LITORA · SOCHI · BLACK SEA</span></div><div class="stay-planner-copy">${eyebrow(t('ВАШЕ ВРЕМЯ У МОРЯ','YOUR TIME BY THE SEA'))}<h2 class="reveal">${t('Пусть следующий<br><em>рассвет будет здесь.</em>','Let the next sunrise<br><em>find you here.</em>')}</h2><p>${t('Начните с дат и состава гостей. Дальше выберем ваше пространство, стол у моря и время для себя.','Begin with your dates and party. Then choose your space, a table beside the sea and time for yourself.')}</p><form id="stay-planner" novalidate><label class="field">${t('Заезд','Check-in')}<input type="date" name="arrival" required min="${todayInSochi()}" aria-describedby="planner-status"></label><label class="field">${t('Выезд','Check-out')}<input type="date" name="departure" required min="${todayInSochi()}" aria-describedby="planner-status"></label><label class="field">${t('Взрослые','Adults')}<select name="adults">${[1,2,3,4].map(n=>`<option ${n===2?'selected':''}>${n}</option>`).join('')}</select></label><button class="pill fill" type="submit">${t('СПЛАНИРОВАТЬ ОТДЫХ','PLAN YOUR STAY')}</button><p id="planner-status" class="small-note" aria-live="polite">${t('Демонстрация бронирования · без оплаты','Reservation demonstration · no payment')}</p></form></div></section>`;}

function home(){return `<section class="hero" id="top">${photo(season==='summer'?'lifestyle-pool-01':'lobby-v2',{cls:'hero-image',eager:true,frame:'cover'})}<div class="hero-atmosphere" aria-hidden="true"></div><div class="hero-birds">${birds()}</div><div class="hero-content"><span class="hero-caption">SOCHI · BLACK SEA · RESORT & SPA</span><h1 class="hero-signature" aria-label="Литора / Litora">Litora</h1><p class="hero-promise">${t('Море ближе. Время медленнее.','Closer to the sea. Further from the rush.')}</p><span class="season-label">${t('ВЫБЕРИТЕ СВОЙ СЕЗОН','CHOOSE YOUR SEASON')}</span>${seasonButtons()}</div><span class="hero-side">${t('ОДНО МЕСТО · ДВА НАСТРОЕНИЯ','ONE PLACE · TWO MOODS')}</span><a href="#our-story" class="hero-discover"><span>${t('НАЧАТЬ ПУТЕШЕСТВИЕ','EXPLORE LITORA')}</span><i aria-hidden="true"></i></a></section>
<section class="section intro-section" id="our-story"><div class="intro-photos"><a href="${href('/resort')}" class="image-link">${photo('lobby-v2',{parallax:true})}</a>${photo('lifestyle-pool-01',{cls:'inset-photo'})}</div><div class="intro-copy">${eyebrow(t('ЛИТОРА · ЧЕРНОМОРСКОЕ ПОБЕРЕЖЬЕ','LITORA · THE BLACK SEA COAST'))}<h2 class="reveal">${t('Создано морем.<br><em>Продумано для вас.</em>','Shaped by the sea.<br><em>Considered for you.</em>')}</h2><p>${t('Один современный отель среди субтропических садов. Плавная линия фасада, террасы над водой и прямая аллея к собственному пляжу. Здесь масштаб большого курорта сочетается с личным пространством.','One contemporary hotel among subtropical gardens. A gently curved façade, terraces above the water and a promenade to the private beach. The scale of a grand resort meets the comfort of personal space.')}</p><p>${t('Пять бассейнов, три разные кухни, восемь термальных пространств и вечера, которые можно провести тихо или с музыкой у моря.','Five pools, three distinct cuisines, eight thermal spaces and evenings spent quietly or with music beside the sea.')}</p>${link('/resort',t('ИСТОРИЯ МЕСТА','OUR STORY'))}</div></section>
<section class="section rooms-section" id="stay"><div class="room-heading">${eyebrow('ROOMS & SUITES')}<h2 class="reveal">${t('Ваше пространство<br><em>рядом с морем.</em>','Your space<br><em>beside the sea.</em>')}</h2></div><div class="tabs" role="tablist" aria-label="${t('Категории номеров','Room categories')}">${rooms.map((r,i)=>`<button role="tab" data-room="${i}" id="room-tab-${i}" aria-selected="${i===roomIndex}" aria-controls="room-theatre" tabindex="${i===roomIndex?0:-1}">${tr(r.name)}</button>`).join('')}</div><div id="room-theatre" role="tabpanel" aria-labelledby="room-tab-${roomIndex}">${roomTheatre()}</div></section>
<section class="panorama">${photo('hero-'+season+'-v2',{parallax:true,frame:'cover'})}<div class="panorama-copy">${eyebrow(t('САДЫ · ТЕРРАСЫ · МОРЕ','GARDENS · TERRACES · SEA'))}<h2 class="reveal">${t('Целый мир.<br><em>На одном берегу.</em>','A world of its own.<br><em>On one shore.</em>')}</h2><p>${t('Откройте карту курорта: от тихого западного сада до концертной сцены и двух пирсов.','Explore the resort map, from the quiet western gardens to the concert stage and two sea piers.')}</p>${link('/resort/territory',t('ИССЛЕДОВАТЬ ТЕРРИТОРИЮ','EXPLORE THE GROUNDS'),'pill')}</div></section>
<section class="section pools-section"><div class="section-head"><div>${eyebrow(t('ПЯТЬ БАССЕЙНОВ · ПЯТЬ СЦЕНАРИЕВ','FIVE POOLS · FIVE WAYS TO UNWIND'))}<h2 class="reveal">${t('Вода в вашем ритме.','Water, at your pace.')}</h2></div>${link('/pools',t('ВСЕ БАССЕЙНЫ','ALL POOLS'))}</div>${rail(facilities.filter(f=>f.group==='pools'),'pool-rail')}</section>
<section class="section dining-section" id="dine"><div class="dining-title"><div>${eyebrow(t('ГАСТРОНОМИЯ · ТРИ КУХНИ','DINING · THREE CUISINES'))}<h2 class="reveal">${t('Южный вкус.<br><em>Ваш сезон.</em>','A taste of the south.<br><em>Your season.</em>')}</h2></div><p>${t('Терраса у воды или стол при свечах. Три ресторана, каждый со своим характером, и сезонная подача, которую хочется рассмотреть ближе.','A terrace by the water or a candlelit table. Three restaurants, each with its own character, and seasonal servings worth a closer look.')}</p></div>${diningFilm()}<div class="venue-list">${venues.map(v=>`<a href="${href('/dining/'+v.id)}"><span class="micro">${tr(v.cuisine)}</span><h3>${tr(v.name)}</h3><p>${v.hours}</p></a>`).join('')}</div></section>
<section class="section wellness-section"><div class="wellness-copy">${eyebrow('SPA & WELLNESS')}<h2 class="reveal">${t('Тепло камня.<br><em>Спокойствие воды.</em>','The warmth of stone.<br><em>The calm of water.</em>')}</h2><p>${t('Крытый бассейн под стеклянной кровлей, хаммам, русская парная и финская сауна. Восемь пространств складываются в термальный маршрут, который можно пройти в собственном темпе.','An indoor pool beneath a glazed roof, a hammam, Russian banya and Finnish sauna. Eight spaces form a thermal circuit to explore at your own pace.')}</p><div class="number-note">${t('Восемь пространств для восстановления.','Eight spaces to restore.')}</div>${link('/wellness',t('ОТКРЫТЬ SPA','EXPLORE THE SPA'),'pill')}</div><div class="wellness-photos">${photo('indoor-v2',{parallax:true})}${photo('spa-hammam-01',{cls:'mini'})}</div></section>
<section class="section experiences-section"><div class="section-head"><div>${eyebrow('EXPERIENCES')}<h2 class="reveal">${t('Дни, наполненные<br><em>вашими желаниями.</em>','Days filled with<br><em>what you love.</em>')}</h2></div><p>${t('Море, движение и музыка. Выберите настроение дня — всё остальное уже рядом.','Sea, movement and music. Choose the mood of your day; everything else is close by.')}</p></div>${rail(['beach','golf','fitness'].map(id=>({...extras[id],name:extras[id].title,path:'/'+id})),'experience-rail')}</section>
<section class="section celebration-section">${photo('celebration-v2',{parallax:true})}<div>${eyebrow(t('ВЕЧЕРА И ЧАСТНЫЕ СОБЫТИЯ','EVENINGS & CELEBRATIONS'))}<h2 class="reveal">${t('Пусть этот вечер<br><em>останется с вами.</em>','Let this evening<br><em>stay with you.</em>')}</h2><p>${tr(extras.celebrations.text)}</p>${link('/celebrations',t('ОСОБЕННЫЕ СОБЫТИЯ','SPECIAL OCCASIONS'))}<br>${link('/events',t('МУЗЫКА И АФИША','MUSIC & WHAT’S ON'))}</div></section>
<section class="section rule"><div class="section-head"><div>${eyebrow(t('ПОВОД ОСТАТЬСЯ','A REASON TO STAY'))}<h2 class="reveal">${t('Больше времени<br><em>для себя.</em>','More time<br><em>for yourself.</em>')}</h2></div>${link('/offers',t('ВСЕ ПРЕДЛОЖЕНИЯ','ALL OFFERS'))}</div><div class="offer-grid">${offers.map(o=>`<article><a href="${href('/offers/'+o.id)}" class="image-link">${photo(o.photo)}</a><h3>${tr(o.name)}</h3><p>${tr(o.text)}</p>${link('/offers/'+o.id,t('ПОСМОТРЕТЬ ПРОГРАММУ','VIEW THE STAY'))}</article>`).join('')}</div></section>
<section class="section rule"><div class="section-head"><div>${eyebrow('LITORA JOURNAL')}<h2 class="reveal">${t('Истории побережья.','Stories from the coast.')}</h2></div>${link('/journal',t('ЧИТАТЬ ЖУРНАЛ','READ THE JOURNAL'))}</div>${journalCards()}</section>${closing()}`;}
function journalCards(){return `<div class="journal-grid">${stories.map(s=>`<article><a class="image-link" href="${href('/journal/'+s.id)}">${photo(s.photo)}</a><h3>${tr(s.title)}</h3><p>${tr(s.intro)}</p>${link('/journal/'+s.id,t('ЧИТАТЬ ИСТОРИЮ','READ THE STORY'))}</article>`).join('')}</div>`;}

// Internal routes are composed by subject rather than duplicating a generic landing page.
function roomPage(r){const d=roomDetails[r.id],keys=roomPhotos(r.id);return pageHero(tr(r.name),`ROOMS & SUITES · ${r.area} M²`,roomPhoto(r.id))+`<section class="section page-intro"><h2 class="reveal">${tr(d.subtitle)}</h2><div><p>${tr(d.text)}</p><div class="detail-strip"><div><span class="micro">${t('ПЛОЩАДЬ','AREA')}</span><strong>${r.area} м²</strong></div><div><span class="micro">${t('ГОСТИ','GUESTS')}</span><strong>${t('до','up to')} ${r.guests}</strong></div><div><span class="micro">${t('САНУЗЛЫ','BATHROOMS')}</span><strong>${d.bath}</strong></div></div>${link('/reservation?room='+r.id,t('ВЫБРАТЬ ЭТОТ НОМЕР','CHOOSE THIS ROOM'),'pill fill')}</div></section><section class="section rule details-layout"><div>${eyebrow(t('ДЕТАЛИ ПРОЖИВАНИЯ','THE DETAILS'))}<h2>${t('Место для вашего<br><em>ритма.</em>','Room for your<br><em>own rhythm.</em>')}</h2><ul class="feature-list">${tr(d.features).map(f=>`<li>${f}</li>`).join('')}<li>${tr(r.view)}</li><li>${d.beds}</li><li>Wi-Fi · ${t('климат-контроль · кофейная станция','climate control · coffee station')}</li></ul></div><div class="floorplan"><img src="/demo/litora/brand/plans/${r.id}.svg" alt="${t('Концептуальная планировка','Conceptual floor plan')}: ${tr(r.name)}"></div></section>${collection(keys.slice(1),{title:t('Ваш номер в деталях.','Your room, in detail.'),kicker:tr(r.name)})}${serviceNotes(t('Остальное уже продумано.','The rest is considered.'),stayServices)}<section class="section rule"><div class="section-head"><h2>${t('Другие категории','Other rooms & suites')}</h2>${link('/rooms',t('ВСЕ НОМЕРА','ALL ROOMS'))}</div><div class="index-grid">${rooms.filter(x=>x.id!==r.id).slice(0,2).map(x=>`<article><a href="${href('/rooms/'+x.id)}" class="image-link">${photo(roomPhoto(x.id))}</a><h3>${tr(x.name)}</h3><p>${x.area} м² · ${tr(x.view)}</p>${link('/rooms/'+x.id,t('ПОСМОТРЕТЬ','EXPLORE'))}</article>`).join('')}</div></section>${closing()}`;}
const catalogueFrames=new Map();
function roomCatalogueRows(items){return items.map((r,i)=>{const d=roomDetails[r.id];return `<article class="room-residence" data-room-row="${r.id}" data-residence-index="${rooms.indexOf(r)}"><div class="catalogue-media">${catalogueFrame(r.id)}</div><div class="catalogue-copy"><div class="residence-heading">${eyebrow(`${String(rooms.indexOf(r)+1).padStart(2,'0')} / ${r.area} M² · ${t('ДО','UP TO')} ${r.guests} ${t('ГОСТЕЙ','GUESTS')}`)}<h2>${tr(r.name)}</h2><p class="catalogue-subtitle">${tr(d.subtitle)}</p></div><div class="residence-details"><p>${tr(d.text)}</p><dl class="room-facts"><div><dt>${t('ГОСТИ','GUESTS')}</dt><dd>${r.guests}</dd></div><div><dt>${t('САНУЗЛЫ','BATHROOMS')}</dt><dd>${d.bath}</dd></div><div><dt>${t('ВИД','VIEW')}</dt><dd>${tr(r.view)}</dd></div></dl><ul class="amenity-tags">${tr(d.features).slice(0,4).map(f=>`<li>${f}</li>`).join('')}</ul><div class="catalogue-actions">${link('/rooms/'+r.id,t('ВСЕ ДЕТАЛИ','EXPLORE THE ROOM'))}${link('/reservation?room='+r.id,t('ВЫБРАТЬ ДАТЫ','CHOOSE DATES'),'pill')}</div></div></div></article>`;}).join('');}

function catalogueFrame(id){const keys=roomPhotos(id),index=(catalogueFrames.get(id)||0)%keys.length;return `<div class="catalogue-shot" data-catalogue-viewport="${id}" tabindex="0" role="group" aria-label="${t('Фотографии номера: используйте стрелки или свайп','Room photographs: use arrow keys or swipe')}"><button class="photo-open" data-photo-open="${keys[index]}" data-photo-prefix="room-${id}-" aria-label="${t('Увеличить фотографию','Enlarge photograph')}">${photo(keys[index])}</button><span class="photo-index">${String(index+1).padStart(2,'0')} / ${String(keys.length).padStart(2,'0')}</span></div><div class="catalogue-controls"><button class="gallery-arrow is-prev" data-catalogue="${id}" data-step="-1" aria-label="${t('Предыдущая фотография','Previous photograph')}">${softArrow}</button><div class="photo-dots">${keys.map((key,i)=>`<button data-catalogue="${id}" data-frame="${i}" aria-label="${t('Фотография','Photograph')} ${i+1}" aria-current="${i===index?'true':'false'}"></button>`).join('')}</div>${pauseControl()}<button class="gallery-arrow" data-catalogue="${id}" data-step="1" aria-label="${t('Следующая фотография','Next photograph')}">${softArrow}</button></div>`;}
function changeCatalogue(id,{step=0,index=null}={}){const keys=roomPhotos(id);if(!keys.length)return;const next=index===null?((catalogueFrames.get(id)||0)+step+keys.length)%keys.length:index;catalogueFrames.set(id,next);const row=document.querySelector(`[data-room-row="${id}"] .catalogue-media`);if(!row)return;dissolvePhoto(row.querySelector('.photo-open'),photo(keys[next]),()=>{const button=row.querySelector('.photo-open');button.dataset.photoOpen=keys[next];row.querySelector('.photo-index').textContent=String(next+1).padStart(2,'0')+' / '+String(keys.length).padStart(2,'0');row.querySelectorAll('[data-frame]').forEach(b=>b.setAttribute('aria-current',String(Number(b.dataset.frame)===next)));});}
function photoSeries(prefix,exclude=[]){return Object.keys(photos).filter(k=>k.startsWith(prefix)&&!exclude.includes(k));}
const albumFrames=new Map();let albumSerial=0;
function collection(keys,{title=t('Рассмотреть ближе','A closer look'),kicker='LITORA · IN DETAIL'}={}){keys=keys.filter(k=>photos[k]);if(keys.some(k=>k.startsWith('dining-bereg-')))keys=['lifestyle-dining-01',...keys];if(!keys.length)return '';const id='album-'+(++albumSerial);return `<section class="section collection-section"><div class="section-head"><div>${eyebrow(kicker)}<h2>${title}</h2></div><span class="micro">${keys.length} ${t('ФОТОГРАФИЙ','PHOTOGRAPHS')}</span></div><div class="media-album" id="${id}" data-album-keys="${keys.join(',')}">${albumStage(id,keys,0)}</div></section>`;}
function albumStage(id,keys,index){const key=keys[index];return `<div class="album-view" data-album-view="${id}" role="group" tabindex="0" aria-label="${t('Фотогалерея: используйте стрелки или свайп','Photographic album: use arrow keys or swipe')}"><button class="photo-open" data-photo-open="${key}" data-photo-collection="${keys.join(',')}" aria-label="${t('Увеличить','Enlarge')}: ${esc(tr(photos[key].alt))}">${photo(key,{cls:'album-photo'})}</button><span class="photo-index">${String(index+1).padStart(2,'0')} / ${String(keys.length).padStart(2,'0')}</span></div><div class="album-caption"><p>${tr(photos[key].alt).replace(/, опорный кадр для видео|, video reference frame/g,'')}</p><div class="album-controls"><button class="gallery-arrow is-prev" data-album="${id}" data-step="-1" aria-label="${t('Предыдущий кадр','Previous photograph')}">${softArrow}</button>${pauseControl()}<button class="gallery-arrow" data-album="${id}" data-step="1" aria-label="${t('Следующий кадр','Next photograph')}">${softArrow}</button></div></div><div class="album-positions" role="group" aria-label="${t('Выбор фотографии','Choose a photograph')}">${keys.map((k,i)=>`<button data-album="${id}" data-frame="${i}" aria-label="${esc(tr(photos[k].alt))}" aria-current="${i===index?'true':'false'}"><span class="sr-only">${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div>`;}
function changeAlbum(id,{step=0,index=null}={}){const element=document.getElementById(id);if(!element)return;const keys=element.dataset.albumKeys.split(','),next=index===null?((albumFrames.get(id)||0)+step+keys.length)%keys.length:index;albumFrames.set(id,next);dissolvePhoto(element.querySelector('.photo-open'),photo(keys[next],{cls:'album-photo'}),()=>{const button=element.querySelector('.photo-open');button.dataset.photoOpen=keys[next];button.setAttribute('aria-label',t('Увеличить: ','Enlarge: ')+tr(photos[keys[next]].alt));element.querySelector('.photo-index').textContent=String(next+1).padStart(2,'0')+' / '+String(keys.length).padStart(2,'0');element.querySelector('.album-caption p').textContent=tr(photos[keys[next]].alt).replace(/, опорный кадр для видео|, video reference frame/g,'');element.querySelectorAll('[data-frame]').forEach(b=>b.setAttribute('aria-current',String(Number(b.dataset.frame)===next)));});}

function serviceNotes(title,items,kicker=t('ПРОДУМАНО В ДЕТАЛЯХ','CONSIDERED IN DETAIL')){return `<section class="section service-notes"><div class="section-head"><div>${eyebrow(kicker)}<h2>${title}</h2></div></div><div class="service-grid">${items.map((item,i)=>`<article><span class="service-number">0${i+1}</span><h3>${tr(item.name)}</h3><p>${tr(item.text)}</p></article>`).join('')}</div></section>`;}
function roomComparison(){return `<section class="section room-comparison rule"><div class="section-head"><div>${eyebrow(t('ПОМОЖЕМ ВЫБРАТЬ','FIND YOUR ROOM'))}<h2>${t('Шесть способов<br><em>остаться у моря.</em>','Six ways to stay<br><em>beside the sea.</em>')}</h2></div><p>${t('Сравните площадь, вместимость и вид. В каждой категории предусмотрены балкон или терраса и собственная ванная.','Compare size, capacity and views. Every category includes a balcony or terrace and a private bathroom.')}</p></div><div class="comparison-scroll" tabindex="0" role="region" aria-label="${t('Сравнение номеров — таблица прокручивается','Room comparison — scrollable table')}"><table><thead><tr><th>${t('Категория','Room')}</th><th>${t('Площадь','Size')}</th><th>${t('Гостей','Guests')}</th><th>${t('Спальни','Bedrooms')}</th><th>${t('Вид','View')}</th></tr></thead><tbody>${rooms.map(r=>`<tr><th scope="row">${link('/rooms/'+r.id,tr(r.name),'')}</th><td>${r.area} м²</td><td>${r.guests}</td><td>${['panorama','family','presidential'].includes(r.id)?(r.id==='panorama'?1:2):1}</td><td>${tr(r.view)}</td></tr>`).join('')}</tbody></table></div></section>`;}

function roomsPage(){return pageHero(t('Просыпаться<br><em>у Чёрного моря.</em>','Wake up<br><em>beside the Black Sea.</em>'),t('НОМЕРА И ЛЮКСЫ · ШЕСТЬ КАТЕГОРИЙ','ROOMS & SUITES · SIX CATEGORIES'),roomPhoto('presidential'),t('От спальни с видом в сад до личной резиденции над побережьем. Выберите пространство для своего отдыха.','From a garden-facing bedroom to a private residence above the coast. Find the setting for your stay.'))+`<section class="section rooms-catalogue-section"><div class="catalogue-filters"><label class="field">${t('Количество гостей','Your party')}<select data-room-filter="guests">${[1,2,3,4].map(n=>`<option value="${n}" ${n===1?'selected':''}>${n} ${t(n===1?'гость':'гостя',n===1?'guest':'guests')}</option>`).join('')}</select></label><label class="field">${t('Вид из номера','Room view')}<select data-room-filter="view"><option value="all">${t('Все виды','All views')}</option><option value="sea">${t('Море','Sea')}</option><option value="garden">${t('Сад','Garden')}</option></select></label><p class="micro" id="room-filter-status" aria-live="polite">${t('6 категорий','6 room categories')}</p></div><div class="rooms-residences" id="room-catalogue">${roomCatalogueRows(rooms)}</div></section>${roomComparison()}${serviceNotes(t('В каждом проживании.','In every stay.'),stayServices)}${closing()}`;}


function facilityPage(f){const detail=facilityDetails[f.id];return pageHero(tr(f.name),f.group==='pools'?t('ПЯТЬ БАССЕЙНОВ','FIVE POOLS'):'SPA & WELLNESS',photoKeyFor(f))+`<section class="section page-intro"><h2>${tr(f.headline)}</h2><div><p>${tr(f.text)}</p><div class="detail-strip"><div><span class="micro">${t('РАСПОЛОЖЕНИЕ','LOCATION')}</span><strong>${tr(f.location)}</strong></div><div><span class="micro">${t('ПОСЕЩЕНИЕ','VISITING')}</span><strong>${tr(f.availability)}</strong></div></div>${link('/resort/territory?place='+f.anchor,t('НАЙТИ НА КАРТЕ','FIND ON THE MAP'))}<br>${link('/reservation?interest='+f.id,t('СПЛАНИРОВАТЬ ПОСЕЩЕНИЕ','PLAN YOUR VISIT'),'pill')}</div></section>${facilityPractical(f,detail)}${collection(photoSeries(f.group==='pools'?'pool-'+f.id+'-':'spa-'+f.id+'-').filter(k=>k!==photoKeyFor(f)),{title:t('Пространство и детали','The space and its details')})}<section class="section rule"><div class="section-head"><h2>${t('Продолжить отдых','Continue your day')}</h2>${link('/'+f.group,f.group==='pools'?t('ВСЕ БАССЕЙНЫ','ALL POOLS'):t('ТЕРМАЛЬНЫЙ МАРШРУТ','THERMAL CIRCUIT'))}</div><div class="index-grid">${facilities.filter(x=>x.group===f.group&&x.id!==f.id).slice(0,2).map(card).join('')}</div></section>${closing()}`;}
function facilityPractical(f,d){if(!d)return '';return `<section class="section facility-practical"><div class="facility-story">${eyebrow(tr(d.mood))}<h2>${tr(d.title)}</h2><p>${tr(d.body)}</p></div><div class="practical-box">${eyebrow(t('ПЕРЕД ПОСЕЩЕНИЕМ','BEFORE YOU VISIT'))}<dl><div><dt>${t('ВРЕМЯ РАБОТЫ','OPENING HOURS')}</dt><dd>${d.hours||'09:00 — 22:00'}</dd></div><div><dt>${t('НА ТЕРРИТОРИИ','ON THE GROUNDS')}</dt><dd>${tr(f.location)}</dd></div>${d.service?`<div><dt>${t('РЯДОМ С ВАМИ','AT HAND')}</dt><dd>${tr(d.service)}</dd></div>`:''}</dl><ul>${tr(d.tips).map(x=>`<li>${x}</li>`).join('')}</ul><p class="small-note">${t('Правила и комфортный формат посещения подскажет команда wellness.','The wellness team can explain the guidelines and help you find a comfortable format.')}</p></div></section>`;}
function ritualSection(){return `<section class="section ritual-section"><div class="section-head"><div>${eyebrow('WELLNESS · LITORA')}<h2>${t('Ваше время<br><em>для восстановления.</em>','Time to rest.<br><em>Your own way.</em>')}</h2></div></div><div class="index-grid">${rituals.map(r=>`<article><a class="image-link" href="${href(r.path)}">${photo(r.photo)}</a><span class="eyebrow">${tr(r.time)}</span><h3>${tr(r.name)}</h3><p>${tr(r.text)}</p>${link(r.path,t('ОТКРЫТЬ ПРОСТРАНСТВО','EXPLORE THE SPACE'))}</article>`).join('')}</div></section>`;}

function card(item){const path=item.path||`/${item.group}/${item.id}`;return `<article><a class="image-link" href="${href(path)}">${photo(item.id==='infinity'?'lifestyle-pool-01':item.photo||photoKeyFor(item))}</a>${item.availability?eyebrow(tr(item.availability)):''}<h3>${tr(item.name||item.title)}</h3><p>${tr(item.text)}</p>${link(path,t('ПОДРОБНЕЕ','EXPLORE'))}</article>`;}
function poolIndex(){return pageHero(t('Пять бассейнов','Five Pools'),t('МОРЕ РЯДОМ · ВОДА ВОКРУГ','THE SEA NEARBY · WATER ALL AROUND'),'pool-infinity-01')+`<section class="section"><div class="section-head"><h2>${t('Выберите свою<br><em>линию воды.</em>','Find your own<br><em>waterline.</em>')}</h2><p>${t('Четыре открытых бассейна и один крытый. Спорт, тишина, сад и главная морская панорама — у каждого собственное место на карте.','Four outdoor pools and one indoor. Training, quiet, gardens and the main sea panorama each have their own place on the map.')}</p></div><div class="index-grid">${facilities.filter(f=>f.group==='pools').map(card).join('')}</div></section>${closing()}`;}
function wellnessIndex(){return pageHero('SPA & Wellness',t('ВОСЕМЬ ТЕРМАЛЬНЫХ ПРОСТРАНСТВ','EIGHT THERMAL SPACES'),'indoor-v2')+`<section class="section page-intro"><h2>${t('Вернуться<br><em>к себе.</em>','Come back<br><em>to yourself.</em>')}</h2><div><p>${t('Западное крыло отеля отдано воде, теплу и тишине. Термальный маршрут соединяет сухие и паровые комнаты, контрастные зоны и места для отдыха. Крытый бассейн остаётся его светлым центром.','The western wing is devoted to water, warmth and quiet. The thermal circuit connects dry and steam rooms, contrast spaces and places to rest. The indoor pool is its light-filled heart.')}</p><p>${t('Индивидуальные уходы, массаж и ритуалы для двоих подбираются по запросу. Перед посещением сотрудники объясняют последовательность и помогают выбрать комфортный сценарий.','Private treatments, massages and rituals for two are arranged on request. The team explains the sequence and helps you choose a comfortable experience.')}</p>${link('/pools/indoor',t('КРЫТЫЙ БАССЕЙН','INDOOR POOL'))}</div></section><section class="section rule"><div class="section-head"><h2>${t('Ваш термальный маршрут','Your thermal circuit')}</h2></div><div class="thermal-index">${facilities.filter(f=>f.group==='wellness').map(f=>`<a class="thermal-item" href="${href(f.path)}">${photo(photoKeyFor(f))}<div><h3>${tr(f.name)}</h3><p>${tr(f.headline)}</p></div></a>`).join('')}</div></section>${ritualSection()}${closing()}`;}
function diningIndex(){return pageHero(t('Три взгляда на вкус','Three Ways to Dine'),t('БЕРЕГ · TERRA · SORA','BEREG · TERRA · SORA'),'dining-bereg-01')+`<section class="section"><div class="section-head"><h2>${t('Каждый вечер —<br><em>свой стол.</em>','A different table.<br><em>Every evening.</em>')}</h2><p>${t('Черноморская, итальянская и японская кухни. У каждого ресторана — отдельное пространство, меню и настроение.','Black Sea, Italian and Japanese cuisines. Each restaurant has its own setting, menu and mood.')}</p></div><div class="room-catalogue">${venues.map(v=>`<article class="catalogue-row">${photo('dining-'+v.id+'-01')}<div>${eyebrow(tr(v.cuisine))}<h2>${tr(v.name)}</h2><p>${tr(v.text)}</p>${link('/dining/'+v.id,t('ОТКРЫТЬ РЕСТОРАН','EXPLORE THE RESTAURANT'))}</div></article>`).join('')}</div></section>${closing()}`;}
function restaurantPage(v){const d=dinnerDetails[v.id];return pageHero(tr(v.name),tr(v.cuisine),'dining-'+v.id+'-01')+`<section class="section page-intro"><h2>${tr(v.cuisine)}</h2><div><p>${tr(v.text)}</p><div class="detail-strip"><div><span class="micro">${t('ВРЕМЯ РАБОТЫ','OPENING HOURS')}</span><strong>${v.hours}</strong></div></div>${link('/resort/territory?place='+v.anchor,t('НА КАРТЕ КУРОРТА','ON THE RESORT MAP'))}<br>${link('/reservation?interest='+v.id,t('СПЛАНИРОВАТЬ УЖИН','PLAN A DINNER'),'pill')}</div></section>${v.id==='bereg'?`<section class="section dining-section">${eyebrow(t('ОДИН РЕСТОРАН · ДВА СЕЗОНА','ONE RESTAURANT · TWO SEASONS'))}<div class="dining-title"><h2>${t('Подача сезона','A seasonal serving')}</h2>${seasonButtons()}</div>${diningFilm()}</section>`:''}<section class="section menu-sample"><div class="section-head"><h2>${t('Сезон на тарелке','The season, on a plate')}</h2><p>${t('Пример меню для концепта. Состав и пищевые предпочтения уточняются перед заказом.','A sample concept menu. Ingredients and dietary preferences are discussed before ordering.')}</p></div>${tr(v.menu).map((m,i)=>`<div class="menu-course"><span>${m}</span><span class="muted">0${i+1}</span></div>`).join('')}</section>${dinnerStory(v,d)}${closing()}`;}
function dinnerStory(v,d){return `<section class="section dining-story"><div class="section-head"><div>${eyebrow(tr(v.name)+' · '+tr(v.cuisine))}<h2>${tr(d.title)}</h2></div><p>${tr(d.text)}</p></div><div class="dish-grid">${d.photos.filter(k=>photos[k]).map((key,i)=>`<article><button class="photo-open" data-photo-open="${key}" data-photo-prefix="dining-${v.id}-" aria-label="${t('Рассмотреть блюдо','View the dish')}">${photo(key)}</button><span class="eyebrow">0${i+1} · ${t('ИЗ МЕНЮ','ON THE MENU')}</span><h3>${tr(d.dishes)[i][0]}</h3><p>${tr(d.dishes)[i][1]}</p></article>`).join('')}</div><div class="dinner-notes"><p>${t('Особый повод, детское меню и пищевые предпочтения можно указать при планировании отдыха.','Add a special occasion, children’s dining or dietary preferences when planning your stay.')}</p>${link('/reservation?interest='+v.id,t('ЗАПЛАНИРОВАТЬ ВЕЧЕР','PLAN AN EVENING'),'pill')}</div></section>${collection(photoSeries('dining-'+v.id+'-').filter(k=>!['dining-'+v.id+'-01',...d.photos].includes(k)),{title:t('Атмосфера ресторана','The restaurant atmosphere'),kicker:tr(v.name)})}`;}
function extraStory(id){const d=extraStories[id];if(!d)return '';return `<section class="section extra-story"><div class="section-head"><h2>${tr(d.title)}</h2><p>${tr(d.text)}</p></div><ol class="day-steps">${tr(d.steps).map(([title,text],i)=>`<li><span class="service-number">0${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></li>`).join('')}</ol>${link(d.related,t('ПРОДОЛЖИТЬ ЗНАКОМСТВО','EXPLORE MORE'))}</section>${collection([...new Set([...d.gallery,...photoSeries(id+'-')])].filter(k=>k!==extras[id].photo),{title:t('Остаться в этом моменте','Stay in the moment')})}`;}

function extraPage(id){const e=extras[id];return pageHero(tr(e.title),tr(e.headline),e.photo)+`<section class="section page-intro"><h2>${tr(e.headline)}</h2><div><p>${tr(e.text)}</p><ul class="feature-list">${tr(e.details).map(d=>`<li>${d}</li>`).join('')}</ul>${link('/reservation?interest='+id,t('СПЛАНИРОВАТЬ ОТДЫХ','PLAN YOUR STAY'),'pill')}${link('/resort/territory',t('КАРТА КУРОРТА','RESORT MAP'))}</div></section>${extraStory(id)}${closing()}`;}

function resortPage(){return pageHero(t('Литора. Свой берег.','Litora. Your Own Shore.'),t('СОЧИ · ЧЕРНОМОРСКОЕ ПОБЕРЕЖЬЕ','SOCHI · THE BLACK SEA COAST'),'hero-'+season+'-v2')+`<section class="section page-intro"><h2>${t('Большой курорт.<br><em>Личное пространство.</em>','A grand resort.<br><em>A personal space.</em>')}</h2><div><p>${t('Литора — один современный отель со связанными крыльями. Ступенчатые террасы и плавный фасад обращены к морю; между корпусом и пляжем лежит большой субтропический сад.','Litora is one contemporary hotel with connected wings. Stepped terraces and a curved façade face the sea; a large subtropical garden lies between the building and the beach.')}</p><p>${t('Тихие маршруты проходят через западную часть: гольф, небольшой подогреваемый бассейн и SPA. Восточная сторона объединяет лагуну, спорт и события. Прямая центральная аллея помогает легко ориентироваться.','Quiet routes lead west to golf, the heated garden pool and SPA. The eastern grounds bring together the lagoon, sport and events. A central promenade makes the resort easy to navigate.')}</p>${link('/resort/territory',t('ОТКРЫТЬ КАРТУ','OPEN THE MAP'),'pill')}</div></section><section class="section"><div class="detail-gallery">${photo('lobby-v2')}${photo('hero-'+season+'-v2')}</div></section>${collection(photoSeries('architecture-').filter(k=>['architecture-06','architecture-09','architecture-12','architecture-13','architecture-14','architecture-18'].includes(k)),{title:t('Архитектура изнутри.','Architecture, from within.'),kicker:'THE RESORT'})}${serviceNotes(t('Внимание к вашему дню.','Your day, considered.'),stayServices)}<section class="section rule"><div class="section-head"><h2>${t('Всё, что делает<br><em>отдых вашим.</em>','Everything that makes<br><em>a stay your own.</em>')}</h2></div><div class="index-grid">${[{name:[t('Шесть категорий номеров','Six room categories')],text:[t('От сада до верхней морской террасы.','From the gardens to the top-floor sea terrace.')],photo:roomPhoto('presidential'),path:'/rooms'},...facilities.filter(f=>['indoor','infinity'].includes(f.id)),{...extras.beach,name:extras.beach.title,path:'/beach'}].map(card).join('')}</div></section>${closing()}`;}

let territory={zones:[]};
try{territory=await(await fetch('/demo/litora/docs/territory.json')).json();}catch{}
function mapPage(){return `<section class="text-page section"><span class="eyebrow">THE GROUNDS OF LITORA</span><h1>${t('Весь курорт.<br><em>Перед вами.</em>','The whole resort.<br><em>Before you.</em>')}</h1><p class="body-copy">${t('Выберите точку на карте или название в списке. Найдите свой бассейн, ресторан и путь к морю.','Select a point on the map or a name below. Find your pool, restaurant and path to the sea.')}</p></section><section class="section map-section"><div class="map-filters" role="group" aria-label="${t('Категории карты','Map categories')}">${[['all',t('Всё','All')],['pool',t('Бассейны','Pools')],['restaurant',t('Рестораны','Restaurants')],['bar',t('Бары','Bars')],['spa','SPA'],['party',t('События','Events')]].map(([id,n])=>`<button data-map-filter="${id}" aria-pressed="${id==='all'}">${n}</button>`).join('')}</div><div class="map-shell"><div class="map-picture"><img src="/demo/litora/brand/masterplan-v2-base.png" alt="${t('Архитектурная карта Литоры','Architectural map of Litora')}">${territory.zones.map((z,i)=>`<button class="map-pin" style="left:${z.x/1536*100}%;top:${z.y/1024*100}%" data-place="${z.id}" data-map-type="${z.type}" aria-label="${esc(language==='en'?z.en:z.name)}" aria-pressed="false">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><div id="map-info" class="map-info" aria-live="polite"></div></div><div class="map-list">${territory.zones.map((z,i)=>`<button data-place="${z.id}" data-map-type="${z.type}" aria-pressed="false">${String(i+1).padStart(2,'0')} &nbsp; ${language==='en'?z.en:z.name}</button>`).join('')}</div><p class="map-note">${t('Архитектурная концепция вымышленного курорта. Западная часть отдана тихому отдыху; восточная — спорту и вечерним событиям. Крытый бассейн расположен в примыкающем SPA-крыле слева.','An architectural concept for a fictional resort. The west is devoted to quiet relaxation; the east to sport and evening events. The indoor pool is in the attached SPA wing on the left.')}</p></section>`;}
function selectPlace(id){const z=territory.zones.find(z=>z.id===id)||territory.zones[0];if(!z)return;document.querySelectorAll('[data-place]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.place===z.id)));let target='/resort',description=t('Общий маршрут по территории отеля.','Explore the hotel grounds.');const f=facilities.find(f=>f.anchor===z.id);if(f){target=f.path;description=tr(f.text);}const v=venues.find(v=>v.anchor===z.id);if(v){target='/dining/'+v.id;description=tr(v.cuisine);}if(z.id==='spa'){target='/wellness';description=t('Крытый бассейн и восемь термальных пространств в западном крыле.','The indoor pool and eight thermal spaces in the western wing.');}if(['beach','golf','fitness'].includes(z.id)){target='/'+z.id;description=tr(extras[z.id].text);}if(z.type==='bar'){target='/bars';description=t('Одна из четырёх барных точек курорта.','One of the resort’s four bars and lounges.');}if(z.type==='party'){target=z.id==='e2'?'/celebrations':'/events';description=t('Восточная событийная зона, отделённая садом от тихой части.','The eastern events area, separated by gardens from the quiet grounds.');}const info=document.querySelector('#map-info');if(info)info.innerHTML=`${eyebrow('LITORA · THE GROUNDS')}<h3>${language==='en'?z.en:z.name}</h3><p>${description}</p>${link(target,t('ПЕРЕЙТИ К МЕСТУ','EXPLORE THIS PLACE'))}`;}
function experiencesPage(){return pageHero(t('Впечатления','Experiences'),t('ДЕНЬ ЗА ДНЁМ · ПО-СВОЕМУ','DAY BY DAY · YOUR OWN WAY'),'beach-v2')+`<section class="section"><div class="section-head"><h2>${t('Чем наполнится<br><em>ваш день?</em>','What will fill<br><em>your day?</em>')}</h2></div><div class="index-grid">${['beach','golf','fitness'].map(id=>card({...extras[id],name:extras[id].title,path:'/'+id})).join('')}${card({name:pairLocal('Музыка и вечера','Music & Evenings'),text:pairLocal('Летняя сцена и камерная зимняя программа.','The summer stage and intimate winter programmes.'),photo:'concert-v2',path:'/events'})}</div></section>${closing()}`;}
function pairLocal(ru,en){return [ru,en];}
function eventIndex(){return pageHero(t('Вечера Литоры','Litora Evenings'),t('МУЗЫКА · УЖИНЫ · ВСТРЕЧИ','MUSIC · DINNERS · GATHERINGS'),'concert-v2')+`<section class="section"><div class="section-head"><h2>${t('Сезон меняется.<br><em>Настроение остаётся.</em>','Seasons change.<br><em>The feeling stays.</em>')}</h2><p>${t('Программы вымышленного курорта: знакомство с форматами без объявления реальных артистов и подтверждённых дат.','Programmes for a fictional resort: discover the formats, without real performers or confirmed event dates.')}</p></div><div class="index-grid">${events.map(e=>card({...e,path:'/events/'+e.id})).join('')}</div></section>${closing()}`;}
function eventPage(e){const isSummer=e.id==='sunset-sessions',isDinner=e.id==='gastronomic-evening';const programme=isDinner?[[t('Встреча','Arrival'),t('Аперитив и знакомство с вечерним меню.','An aperitif and an introduction to the evening menu.')],[t('Подачи','The courses'),t('Сезонные блюда, рассказ о продуктах и сочетаниях.','Seasonal dishes with stories about produce and pairings.')],[t('После ужина','After dinner'),t('Десерт, кофе и прогулка по морской террасе.','Dessert, coffee and a walk along the sea terrace.')]]:isSummer?[[t('К закату','At sunset'),t('Встреча в восточном саду, напитки и свободная посадка.','Meet in the eastern gardens for drinks and relaxed seating.')],[t('Живой звук','Live sound'),t('Джаз или акустический сет на открытой сцене.','Jazz or an acoustic set on the open-air stage.')],[t('Поздний вечер','Later in the evening'),t('DJ-программа и продолжение вечера в Beach Bar.','A DJ programme and the evening continues at Beach Bar.')]]:[[t('После SPA','After the SPA'),t('Спокойный ужин в одном из трёх ресторанов.','An unhurried dinner at one of the three restaurants.')],[t('Вечер','The evening'),t('Небольшая акустическая программа в Lobby Lounge.','An intimate acoustic programme at Lobby Lounge.')],[t('Завершение','To finish'),t('Чай, коктейль или десерт за своим столиком.','Tea, a cocktail or dessert at your table.')]];return pageHero(tr(e.name),isSummer?t('ЛЕТНЯЯ ПРОГРАММА','SUMMER PROGRAMME'):isDinner?t('ГАСТРОНОМИЧЕСКИЙ ВЕЧЕР','GASTRONOMIC EVENING'):t('ЗИМНЯЯ ПРОГРАММА','WINTER PROGRAMME'),e.photo)+`<section class="section page-intro"><h2>${tr(e.headline)}</h2><div><p>${tr(e.text)}</p><p>${t('Выберите настроение вечера, а предпочтения по времени и формату добавьте к плану поездки.','Choose the mood of your evening and add your preferred time and format to your stay plans.')}</p>${link('/reservation?interest='+e.id,t('ДОБАВИТЬ К ПЛАНАМ','ADD TO YOUR STAY'),'pill')}</div></section><section class="section extra-story"><div class="section-head"><div>${eyebrow(t('КАК ПРОХОДИТ ВЕЧЕР','HOW THE EVENING UNFOLDS'))}<h2>${t('Остаться<br><em>в настроении вечера.</em>','Stay a little longer.<br><em>Follow the evening.</em>')}</h2></div><p>${t('Открытая площадка находится в восточной части курорта; камерные зимние события проходят внутри отеля. Это концептуальная программа без реальных анонсов и продажи билетов.','The open-air venue is on the eastern grounds; intimate winter gatherings take place indoors. This is a concept programme without real event announcements or ticket sales.')}</p></div><ol class="day-steps">${programme.map(([name,text],i)=>`<li><span class="service-number">0${i+1}</span><div><h3>${name}</h3><p>${text}</p></div></li>`).join('')}</ol>${link('/resort/territory?place='+ (isDinner?'r1':isSummer?'e1':'b1'),t('МЕСТО НА КАРТЕ','FIND THE VENUE'))}</section>${collection((isSummer?['event-garden-party-01','bar-beach-01']:isDinner?['dining-bereg-05','dining-bereg-07']:['bar-candlelight-01','service-winter-tea-01']).filter(k=>k!==e.photo),{title:t('Ваш вечер в деталях','Your evening, in detail')})}${closing()}`;}

function offersPage(){return pageHero(t('Поводы остаться','Reasons to Stay'),t('ПРЕДЛОЖЕНИЯ СЕЗОНА','SEASONAL STAYS'),'hero-'+season+'-v2')+`<section class="section"><div class="index-grid">${offers.map(o=>card({...o,path:'/offers/'+o.id})).join('')}</div></section>${closing()}`;}
function offerPage(o){const winter=o.id==='winter-wellness';const days=winter?[[t('День прибытия','Arrival day'),t('Разместиться, прогуляться по зимнему берегу и выбрать стол для ужина.','Settle in, walk along the winter shore and choose your dinner table.')],[t('День для себя','A day for yourself'),t('Завтрак в Terra, крытый бассейн и спокойный термальный маршрут.','Breakfast at Terra, the indoor pool and an unhurried thermal circuit.')],[t('Без спешки','Take your time'),t('Тёплая вода в западном саду, чай в lounge и ещё одна прогулка к морю.','Warm water in the western gardens, tea at the lounge and one more coastal walk.')]]:[[t('Первые дни','The first days'),t('Познакомиться с территорией, выбрать любимый бассейн и свой маршрут к пляжу.','Discover the grounds, find your favourite pool and your own route to the beach.')],[t('В середине недели','Midweek'),t('Попробовать три кухни, посвятить утро SPA или тренировке и остаться на музыкальный вечер.','Try three cuisines, spend a morning at the SPA or training and stay for an evening of music.')],[t('Ваш собственный ритм','Your own rhythm'),t('Завтрак на террасе, прогулка по пирсу и день, который не нужно планировать заранее.','Breakfast on the terrace, a walk along the pier and a day that needs no advance plans.')]];return pageHero(tr(o.name),t('ПРОГРАММА ОТДЫХА','A CONSIDERED STAY'),o.photo)+`<section class="section page-intro"><h2>${tr(o.headline)}</h2><div><p>${tr(o.text)}</p><ul class="feature-list">${tr(o.includes).map(i=>`<li>${i}</li>`).join('')}</ul>${link('/reservation?offer='+o.id,t('ВЫБРАТЬ ДАТЫ','CHOOSE YOUR DATES'),'pill fill')}<p class="booking-note">${t('Концептуальное предложение для портфолио. Оплата не производится; стоимость и реальная доступность не заявляются.','A concept stay for the portfolio. No payment is taken; prices and real availability are not advertised.')}</p></div></section><section class="section extra-story"><div class="section-head"><div>${eyebrow(t('ИДЕИ ДЛЯ ВАШИХ ДНЕЙ','IDEAS FOR YOUR DAYS'))}<h2>${t('Отдых уже<br><em>складывается.</em>','Your stay is<br><em>taking shape.</em>')}</h2></div></div><ol class="day-steps">${days.map(([name,text],i)=>`<li><span class="service-number">0${i+1}</span><div><h3>${name}</h3><p>${text}</p></div></li>`).join('')}</ol></section>${collection(winter?['pool-quiet-01','service-winter-tea-01','bar-rooftop-winter-01']:['beach-v2','dining-terra-01','golf-v2'],{title:t('Всё рядом.','All close at hand.')})}<section class="section rule"><div class="section-head"><h2>${t('Выберите пространство.','Choose your space.')}</h2>${link('/rooms',t('ВСЕ НОМЕРА','ALL ROOMS'))}</div><div class="index-grid">${rooms.filter(r=>winter?['sea-deluxe','panorama'].includes(r.id):['junior-terrace','family'].includes(r.id)).map(r=>card({name:r.name,text:roomDetails[r.id].text,photo:roomPhoto(r.id),path:'/rooms/'+r.id})).join('')}</div></section>${closing()}`;}

function barsPage(){return pageHero(t('Четыре точки встречи','Four Places to Meet'),'BARS & LOUNGES',photos['bar-rooftop-01']?'bar-rooftop-01':'lobby-v2')+`<section class="section bars-intro"><div class="section-head"><h2>${t('От утреннего кофе<br><em>до последнего заката.</em>','From morning coffee<br><em>to the last sunset.</em>')}</h2><p>${t('У каждого времени дня — своё место. Лобби, бассейн, пляж и верхняя терраса связаны одним маршрутом по территории.','Every hour has its own setting. Lobby, pool, beach and rooftop follow one route through the resort.')}</p></div><div class="bar-catalogue">${barDetails.map(b=>`<article class="bar-row"><button class="photo-open" data-photo-open="${photos[b.photo]?b.photo:b.fallback}" aria-label="${b.name}">${photo(season==='winter'&&b.id==='b4'&&photos['bar-rooftop-winter-01']?'bar-rooftop-winter-01':photos[b.photo]?b.photo:b.fallback)}</button><div>${eyebrow(tr(b.location))}<h2>${b.name}</h2><p class="bar-headline">${tr(b.headline)}</p><p>${tr(b.text)}</p><span class="bar-hours">${b.hours}</span><ul class="amenity-tags">${tr(b.menu).map(x=>`<li>${x}</li>`).join('')}</ul>${link('/resort/territory?place='+b.id,t('НАЙТИ НА КАРТЕ','FIND ON THE MAP'))}</div></article>`).join('')}</div></section>${closing()}`;}

function journalPage(id){if(id){const s=stories.find(s=>s.id===id),keys=({architecture:['architecture-12','architecture-13'], 'black-sea-table':['dining-terra-06','dining-sora-05'],'winter-by-the-sea':['architecture-18','pool-quiet-05']})[id].filter(k=>photos[k]);return pageHero(tr(s.title),'LITORA JOURNAL',s.photo)+`<article class="section prose"><p><em>${tr(s.intro)}</em></p>${tr(s.paragraphs).map((p,i)=>`${i?photo(keys[(i-1)%Math.max(keys.length,1)]||s.photo):''}<p>${p}</p>`).join('')}${link('/journal',t('ВСЕ ИСТОРИИ','ALL STORIES'))}</article>${closing()}`;}return pageHero(t('Журнал Литоры','Litora Journal'),t('ИСТОРИИ МЕСТА','STORIES OF A PLACE'),'hero-'+season+'-v2')+`<section class="section">${journalCards()}</section>`;}
function galleryPage(){const groups=[['all',t('Все кадры','All images')],['architecture',t('Архитектура','Architecture')],['rooms',t('Номера','Rooms')],['pools',t('Бассейны','Pools')],['dining',t('Гастрономия','Dining')],['wellness','SPA'],['experiences',t('Впечатления','Experiences')]];return `<section class="section text-page"><span class="eyebrow">LITORA GALLERY</span><h1>${t('Место в деталях.','A Place in Detail.')}</h1><div class="tabs" role="group" aria-label="${t('Фильтр фотографий','Filter photographs')}">${groups.map(([id,n])=>`<button data-gallery-filter="${id}" aria-pressed="${id==='all'}">${n}</button>`).join('')}</div><div id="gallery-grid" class="gallery-grid"></div></section>`;}
function galleryRender(group='all'){lightboxItems=Object.entries(photos).filter(([k,p])=>group==='all'||p.group===group);const grid=document.querySelector('#gallery-grid');if(grid)grid.innerHTML=lightboxItems.map(([key,p],i)=>`<button data-lightbox="${i}" aria-label="${esc(tr(p.alt))}">${photo(key)}<span class="caption-row">${tr(p.alt)}</span></button>`).join('')||`<p class="empty-message">${t('Эта фотосерия ещё готовится.','This photographic series is still being prepared.')}</p>`;}
function openPhoto(index){lightboxIndex=(index+lightboxItems.length)%lightboxItems.length;const [key,p]=lightboxItems[lightboxIndex];if(!lightbox.open)lightbox.showModal();dissolvePhoto(lightbox.querySelector('.lightbox-media'),photo(key,{eager:true}),()=>{lightbox.querySelector('p').textContent=tr(p.alt);});}
function faqPage(){return `<section class="section text-page">${eyebrow('LITORA · YOUR QUESTIONS')}<h1>${t('Полезно знать.','Good to Know.')}</h1><div class="faq-list">${tr(faq).map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>${closing()}`;}
function contactsPage(){return pageHero(t('Встретимся у моря','Meet Us by the Sea'),t('СОЧИ · ЧЕРНОМОРСКОЕ ПОБЕРЕЖЬЕ','SOCHI · THE BLACK SEA COAST'),'hero-summer-v2')+`<section class="section page-intro"><h2>${t('Путь к вашему<br><em>отдыху.</em>','The way to<br><em>your stay.</em>')}</h2><div><p>${t('Литора — вымышленный курорт в Сочи. Точный адрес, действующий телефон и транспортный маршрут не заявляются: проект создан для демонстрации дизайна и сценария отдыха.','Litora is a fictional resort in Sochi. There is no real address, active phone number or transport route: the project demonstrates design and a hospitality journey.')}</p><p>${t('В концепции предусмотрены подъезд к главному лобби, зона высадки и парковка за корпусом. Пожелания к прибытию можно добавить в демонстрационную форму.','The concept includes a main-lobby approach, a drop-off area and parking behind the hotel. Add arrival preferences in the demonstration form.')}</p>${link('/reservation',t('СПЛАНИРОВАТЬ ПРИБЫТИЕ','PLAN YOUR ARRIVAL'),'pill')}${link('/resort/territory',t('ПОСМОТРЕТЬ ТЕРРИТОРИЮ','EXPLORE THE GROUNDS'))}</div></section>${serviceNotes(t('От дороги —<br><em>к отдыху.</em>','From the journey<br><em>to your stay.</em>'),[{name:pairLocal('Прибытие','Arrival'),text:pairLocal('Зона высадки расположена у главного лобби. Парковка и сервисный подъезд остаются за зданием; пляжная территория свободна от автомобилей.','The drop-off area is beside the main lobby. Parking and service access stay behind the building; the beachfront grounds remain free of cars.')},{name:pairLocal('Ваши пожелания','Your preferences'),text:pairLocal('Время прибытия, багаж, поездку с детьми и особый повод можно указать в форме. Данные этой демонстрации остаются в браузере.','Add your arrival time, luggage, children and any special occasion to the form. Information in this demonstration stays in your browser.')},{name:pairLocal('После встречи','After your welcome'),text:pairLocal('Выберите номер, познакомьтесь с маршрутом до моря и загляните в Lobby Lounge. Команда консьержа предусмотрена в центральном лобби.','Choose your room, find your route to the sea and stop by Lobby Lounge. The concierge is located in the central lobby.')}])}${collection(['service-arrival-01','service-concierge-01'],{title:t('Добро пожаловать в Литору.','Welcome to Litora.')})}`;}
function bookingPage(){const q=new URLSearchParams(location.search),chosen=q.get('room')||'',interest=q.get('interest')||q.get('offer')||'';return `<section class="section text-page">${eyebrow(t('ВАШЕ СЛЕДУЮЩЕЕ ПУТЕШЕСТВИЕ','YOUR NEXT CHAPTER'))}<h1>${t('Остаться<br><em>у моря.</em>','Stay<br><em>beside the sea.</em>')}</h1><div class="reservation-layout"><aside class="reservation-summary">${photo(roomPhoto(chosen||'sea-deluxe'))}<h3>${t('Выберите свой ритм.','Choose your pace.')}</h3><p class="booking-note">${t('Демонстрация бронирования. После заполнения вы увидите резюме поездки. Данные остаются в этой вкладке, заявка не отправляется, оплата не производится.','A reservation demonstration. After completing the form, you will see a stay summary. Details remain in this tab; no request is sent and no payment is taken.')}</p>${interest?`<p>${t('Ваш интерес','Your interest')}: ${esc(interestLabel(interest))}</p>`:''}</aside><form id="booking" class="booking-form" novalidate>${field('arrival',t('Заезд','Check-in'),'date',q.get('arrival')||'',`min="${todayInSochi()}"`)}${field('departure',t('Выезд','Check-out'),'date',q.get('departure')||'',`min="${todayInSochi()}"`)}<label class="field">${t('Взрослые','Adults')}<select name="adults" id="adults" aria-describedby="error-adults">${[1,2,3,4].map(n=>`<option ${n===Number(q.get('adults')||2)?'selected':''}>${n}</option>`).join('')}</select><span class="field-error" id="error-adults" data-error="adults"></span></label><label class="field">${t('Дети','Children')}<select name="children" id="children" aria-describedby="error-children">${[0,1,2,3].map(n=>`<option>${n}</option>`).join('')}</select><span class="field-error" id="error-children" data-error="children"></span></label><label class="field full">${t('Категория номера','Room category')}<select name="room" id="booking-room" aria-describedby="error-room"><option value="">${t('Помогите мне выбрать','Help me choose')}</option>${rooms.map(r=>`<option value="${r.id}" ${r.id===chosen?'selected':''}>${tr(r.name)} — ${r.area} м² · ${t('до','up to')} ${r.guests} ${t('гостей','guests')}</option>`).join('')}</select><span class="field-error" id="error-room" data-error="room"></span></label>${field('name',t('Имя и фамилия','Full name'),'text','', 'autocomplete="name"')}${field('email','E-mail','email','','autocomplete="email"')}<label class="field full">${t('Пожелания к отдыху','Your preferences')}<textarea name="notes" maxlength="1500" placeholder="${t('Прибытие, питание, особый повод…','Arrival, dining, a special occasion…')}"></textarea></label><label class="check-field full"><input type="checkbox" name="consent" aria-describedby="error-consent"><span>${t('Я понимаю, что это демонстрация, и согласен с','I understand this is a demonstration and agree to the')} ${link('/terms',t('условиями проекта','project terms'),'')}.</span></label><span class="field-error full" id="error-consent" data-error="consent"></span><button class="pill fill full" type="submit">${t('ПОСМОТРЕТЬ МОЮ ПОЕЗДКУ','PREVIEW MY STAY')}</button><div id="booking-result" class="full" aria-live="polite"></div></form></div></section>`;}
function field(name,label,type='text',value='',attrs=''){return `<label class="field">${label}<input id="${name}" name="${name}" aria-describedby="error-${name}" type="${type}" value="${esc(value)}" ${attrs} required><span class="field-error" id="error-${name}" data-error="${name}"></span></label>`;}
function legalPage(type){return `<section class="section text-page legal-page"><span class="eyebrow">LITORA · PORTFOLIO CONCEPT</span><h1>${routeName('/'+type)}</h1><div class="prose">${type==='privacy'?`<h2>${t('Ваши данные в демонстрации','Your data in the demonstration')}</h2><p>${t('Форма бронирования обрабатывается в браузере и не отправляет данные на сервер. После обновления страницы введённые имя, e-mail и пожелания не сохраняются. Форма подписки также демонстрационная и не подключена к рассылке.','The booking form runs in your browser and sends nothing to a server. Names, email addresses and notes are not saved after a page reload. The newsletter form is also a demonstration and is not connected to a mailing service.')}</p><h2>${t('Локальные настройки','Local preferences')}</h2><p>${t('Сайт запоминает только выбранный язык и сезон в локальном хранилище браузера. Заставка использует память текущей сессии, чтобы не повторяться полностью при каждом переходе. Аналитика и рекламные трекеры не подключены.','The site stores only your chosen language and season in browser local storage. The introduction uses session storage so it does not repeat in full at every visit. No analytics or advertising trackers are connected.')}</p>`:`<h2>${t('Вымышленный курорт','A fictional resort')}</h2><p>${t('Литора — авторский портфолио-проект. Отель, архитектура, услуги, меню и предложения созданы для демонстрации. Бронирование не создаёт обязательств, не подтверждает наличие номера и не принимает оплату.','Litora is an original portfolio project. The hotel, architecture, services, menus and offers are created for demonstration. A booking does not create an obligation, confirm availability or accept payment.')}</p><h2>${t('Фотографии и программа','Imagery and programmes')}</h2><p>${t('Изображения и сезонные ролики созданы с помощью генеративных моделей. Они изображают концепцию курорта. Программа событий не является анонсом реальных артистов. Площади и вместимость номеров — параметры вымышленного проекта.','Images and seasonal films were created with generative models and depict the resort concept. Event programmes do not announce real performers. Room sizes and capacities are parameters of the fictional project.')}</p>`}</div></section>`;}
function contentFor(path){const r=getRoute(path),parts=path.split('/').filter(Boolean);if(r.type==='notfound')return `<section class="notfound"><span class="eyebrow">404 · LITORA</span><h1>${t('Этот путь<br>ведёт к морю.','This path<br>leads to the sea.')}</h1><p>${t('Такой страницы нет. Вернёмся к курорту?','This page does not exist. Return to the resort?')}</p>${link('/',t('НА ГЛАВНУЮ','BACK HOME'),'pill')}</section>`;if(path==='/')return home();if(r.type==='room')return roomPage(r.item);if(r.type==='restaurant')return restaurantPage(venues.find(v=>v.id===parts[1]));if(path==='/resort/territory')return mapPage();if(path==='/resort')return resortPage();if(path==='/rooms')return roomsPage();if(path==='/dining')return diningIndex();if(path==='/wellness')return wellnessIndex();if(path==='/pools')return poolIndex();if(facilities.some(f=>f.path===path))return facilityPage(facilities.find(f=>f.path===path));if(extras[parts[0]])return extraPage(parts[0]);if(path==='/bars')return barsPage();if(path==='/experiences')return experiencesPage();if(path==='/events')return eventIndex();if(parts[0]==='events')return eventPage(events.find(e=>e.id===parts[1]));if(path==='/offers')return offersPage();if(parts[0]==='offers')return offerPage(offers.find(o=>o.id===parts[1]));if(parts[0]==='journal')return journalPage(parts[1]);if(path==='/gallery')return galleryPage();if(path==='/faq')return faqPage();if(path==='/contacts')return contactsPage();if(path==='/reservation')return bookingPage();return legalPage(parts[0]);}
function captureDraft(){const form=document.querySelector('#booking');if(!form)return;const values=Object.fromEntries(new FormData(form));values.consent=form.elements.consent.checked;bookingDraft=makeBookingDraft(values);}
function refreshBookingPreview(){const form=document.querySelector('#booking'),image=document.querySelector('.reservation-summary .photo');if(!form||!image)return;const id=form.elements.room.value||'sea-deluxe';image.outerHTML=photo(roomPhoto(id));}
function restoreDraft({preserveDraft=false}={}){const form=document.querySelector('#booking');if(!form||!bookingDraft)return;for(const [key,value] of Object.entries(bookingDraft)){const field=form.elements[key];if(!field)continue;if(field.type==='checkbox')field.checked=value===true;else field.value=value;}const query=new URLSearchParams(location.search);if(!preserveDraft)for(const key of ['room','arrival','departure','adults'])if(query.has(key))form.elements[key].value=query.get(key);refreshBookingPreview();}
function render({focus=false,preserveDraft=false}={}){captureDraft();document.documentElement.dataset.motion=prefersQuiet()?'quiet':'full';albumSerial=0;albumFrames.clear();cleanup();document.documentElement.lang=language;nav();footer();const path=currentPath()||'/';main.dataset.section=path.split('/').filter(Boolean)[0]||'home';document.body.classList.toggle('plain-page',['/reservation','/gallery','/faq','/privacy','/terms','/resort/territory'].includes(path));main.innerHTML=contentFor(path);restoreDraft({preserveDraft});document.title=`${path==='/'?t('Жизнь у моря','Life by the Sea'):routeName(path)} — LITORA`;if(path==='/gallery')galleryRender();const disposers=[setupMotion(main),setupFilm(main,{language}),setupRails(main),setupFluid(main,{album:changeAlbum,catalogue:changeCatalogue,room:()=>{roomImageIndex=(roomImageIndex+1)%Math.max(roomPhotos(rooms[roomIndex].id).length,1);refreshRoom({photoOnly:true});},language,onPreferenceChange:()=>{const y=scrollY;render({preserveDraft:true});window.scrollTo({top:y,behavior:'instant'});}})];cleanup=()=>disposers.forEach(d=>d?.());if(path==='/resort/territory')selectPlace(new URLSearchParams(location.search).get('place')||'hotel');if(focus)main.focus({preventScroll:true});document.querySelector('#announcer').textContent=document.title;}
function readURL(){const q=new URLSearchParams(location.search);language=q.get('lang')==='en'?'en':'ru';season=q.get('season')==='winter'?'winter':'summer';}
async function navigate(url,{replace=false,preserveScroll=false}={}){if(menu.open)await closeSoftMenu(menu);const full=new URL(url,location.origin),scrollPosition=preserveScroll?scrollY:0;await transitionPage(()=>{history[replace?'replaceState':'pushState']({},'',full.pathname+full.search+full.hash);readURL();render({focus:!preserveScroll,preserveDraft:preserveScroll});window.scrollTo({top:scrollPosition,behavior:'instant'});if(full.hash&&!preserveScroll)requestAnimationFrame(()=>document.querySelector(full.hash)?.scrollIntoView());});}
function setPreference(type,value){if(type==='language')language=value;else season=value;storage.set('litora-'+type,value);const url=new URL(location.href);url.searchParams.set('lang',language);url.searchParams.set('season',season);return navigate(url,{replace:true,preserveScroll:true});}
document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.hasAttribute('data-photo-open')&&performance.now()<suppressPhotoClickUntil){e.preventDefault();return;}if(target.matches('a[href]')){const url=new URL(target.href,location.origin);if(url.origin!==location.origin||target.target||target.hasAttribute('download')||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button!==0)return;if(url.pathname===location.pathname&&url.search===location.search&&url.hash)return;e.preventDefault();navigate(url);return;}if(target.matches('[data-motion-toggle]')){const y=scrollY;toggleMotion();render({preserveDraft:true});window.scrollTo({top:y,behavior:'instant'});document.querySelector('[data-motion-toggle]')?.focus({preventScroll:true});}if(target.matches('[data-menu]')){openSoftMenu(menu);}if(target.matches('[data-menu-close]'))closeSoftMenu(menu);if(target.matches('[data-language]'))setPreference('language',language==='ru'?'en':'ru');if(target.matches('[data-season-toggle]'))setPreference('season',season==='summer'?'winter':'summer');if(target.dataset.season&&target.dataset.season!==season)setPreference('season',target.dataset.season);if(target.hasAttribute('data-top'))window.scrollTo({top:0,behavior:prefersQuiet()?'instant':'smooth'});if(target.hasAttribute('data-room')){roomIndex=Number(target.dataset.room);roomImageIndex=0;refreshRoom();}if(target.hasAttribute('data-room-photo')){const total=Math.max(roomPhotos(rooms[roomIndex].id).length,1);roomImageIndex=(roomImageIndex+Number(target.dataset.roomPhoto)+total)%total;refreshRoom({photoOnly:true});}if(target.hasAttribute('data-rail')){const rail=document.getElementById(target.dataset.rail);rail.scrollBy({left:rail.clientWidth*.8*Number(target.dataset.direction),behavior:prefersQuiet()?'instant':'smooth'});}if(target.hasAttribute('data-place'))selectPlace(target.dataset.place);if(target.hasAttribute('data-map-filter')){const filter=target.dataset.mapFilter;document.querySelectorAll('[data-map-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));document.querySelectorAll('[data-map-type]').forEach(b=>b.hidden=filter!=='all'&&b.dataset.mapType!==filter);}if(target.hasAttribute('data-gallery-filter')){document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));galleryRender(target.dataset.galleryFilter);}if(target.hasAttribute('data-photo-open')){const key=target.dataset.photoOpen;const keys=target.dataset.photoCollection?.split(',')||(target.dataset.photoPrefix?photoSeries(target.dataset.photoPrefix):[key]);lightboxItems=keys.filter(k=>photos[k]).map(k=>[k,photos[k]]);openPhoto(Math.max(0,lightboxItems.findIndex(([k])=>k===key)));}if(target.hasAttribute('data-album'))changeAlbum(target.dataset.album,{step:Number(target.dataset.step||0),index:target.dataset.frame===undefined?null:Number(target.dataset.frame)});if(target.hasAttribute('data-catalogue'))changeCatalogue(target.dataset.catalogue,{step:Number(target.dataset.step||0),index:target.dataset.frame===undefined?null:Number(target.dataset.frame)});if(target.hasAttribute('data-lightbox'))openPhoto(Number(target.dataset.lightbox));if(target.hasAttribute('data-lightbox-close'))lightbox.close();if(target.hasAttribute('data-lightbox-prev'))openPhoto(lightboxIndex-1);if(target.hasAttribute('data-lightbox-next'))openPhoto(lightboxIndex+1);});
menu.addEventListener('close',()=>{document.body.classList.remove('menu-is-open');document.querySelector('[data-menu]')?.setAttribute('aria-expanded','false');});
menu.addEventListener('cancel',e=>{e.preventDefault();closeSoftMenu(menu);});
function refreshRoom({photoOnly=false}={}){document.querySelectorAll('[data-room]').forEach(b=>{const active=Number(b.dataset.room)===roomIndex;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});const panel=document.querySelector('#room-theatre');if(!panel)return;panel.setAttribute('aria-labelledby','room-tab-'+roomIndex);const r=rooms[roomIndex];if(photoOnly){dissolvePhoto(panel.querySelector('.room-media-frame'),photo(roomPhoto(r.id,roomImageIndex),{cls:'room-photo'}),()=>{const counter=panel.querySelector('.counter');if(counter)counter.textContent=String(roomImageIndex+1).padStart(2,'0')+' / '+roomPhotos(r.id).length;});return;}const temp=document.createElement('template');temp.innerHTML=roomTheatre();const newStage=temp.content.firstElementChild;const oldStage=panel.querySelector('.room-stage');if(!oldStage){panel.replaceChildren(newStage);return;}dissolvePhoto(oldStage.querySelector('.room-media-frame'),photo(roomPhoto(r.id,roomImageIndex),{cls:'room-photo'}));const copy=oldStage.querySelector('.room-copy');copy.innerHTML=newStage.querySelector('.room-copy').innerHTML;if(!prefersQuiet())copy.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:550,easing:'cubic-bezier(.22,1,.36,1)'});oldStage.querySelector('.counter').textContent='01 / '+roomPhotos(r.id).length;}
document.addEventListener('keydown',e=>{if(lightbox.open&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();openPhoto(lightboxIndex+(e.key==='ArrowRight'?1:-1));}const album=e.target.closest('[data-album-view]');if(album&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const id=album.dataset.albumView;changeAlbum(id,{step:e.key==='ArrowRight'?1:-1});document.querySelector(`[data-album-view="${id}"]`)?.focus();}const viewport=e.target.closest('[data-catalogue-viewport]');if(viewport&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const id=viewport.dataset.catalogueViewport;changeCatalogue(id,{step:e.key==='ArrowRight'?1:-1});document.querySelector(`[data-catalogue-viewport="${id}"]`)?.focus();}const tab=e.target.closest('[data-room]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();roomIndex=e.key==='Home'?0:e.key==='End'?rooms.length-1:(roomIndex+(e.key==='ArrowRight'?1:-1)+rooms.length)%rooms.length;roomImageIndex=0;refreshRoom();document.querySelector(`[data-room="${roomIndex}"]`).focus();}});
let suppressPhotoClickUntil=0;
let pointerX=0,pointerY=0,lightboxPointerX=null,cataloguePointer=null,albumPointer=null;document.addEventListener('pointerdown',e=>{const a=e.target.closest('[data-album-view]');if(a)albumPointer={id:a.dataset.albumView,x:e.clientX,y:e.clientY};const cat=e.target.closest('[data-catalogue-viewport]');if(cat)cataloguePointer={id:cat.dataset.catalogueViewport,x:e.clientX,y:e.clientY};if(e.target.closest('#room-theatre .room-photo')){pointerX=e.clientX;pointerY=e.clientY;}if(lightbox.open&&e.target===lightbox.querySelector('img'))lightboxPointerX=e.clientX;});document.addEventListener('pointerup',e=>{if(albumPointer){const dx=e.clientX-albumPointer.x,dy=e.clientY-albumPointer.y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)){suppressPhotoClickUntil=performance.now()+450;changeAlbum(albumPointer.id,{step:dx<0?1:-1});}albumPointer=null;}if(cataloguePointer){const dx=e.clientX-cataloguePointer.x,dy=e.clientY-cataloguePointer.y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)){suppressPhotoClickUntil=performance.now()+450;changeCatalogue(cataloguePointer.id,{step:dx<0?1:-1});}cataloguePointer=null;}if(lightbox.open&&lightboxPointerX!==null){const delta=e.clientX-lightboxPointerX;lightboxPointerX=null;if(Math.abs(delta)>60)openPhoto(lightboxIndex+(delta<0?1:-1));}if(e.target.closest('#room-theatre .room-photo')&&Math.abs(e.clientX-pointerX)>60&&Math.abs(e.clientX-pointerX)>Math.abs(e.clientY-pointerY)){roomImageIndex=(roomImageIndex+(e.clientX<pointerX?1:-1)+Math.max(roomPhotos(rooms[roomIndex].id).length,1))%Math.max(roomPhotos(rooms[roomIndex].id).length,1);refreshRoom({photoOnly:true});}});
document.addEventListener('dragstart',e=>{if(e.target.closest('.photo,.album-view,.catalogue-shot'))e.preventDefault();});
document.addEventListener('pointercancel',()=>{cataloguePointer=null;albumPointer=null;lightboxPointerX=null;});
document.addEventListener('change',e=>{if(e.target.matches('#booking-room'))refreshBookingPreview();if(e.target.matches('[data-room-filter]')){const guests=document.querySelector('[data-room-filter=guests]').value,view=document.querySelector('[data-room-filter=view]').value,items=filterRooms({guests,view});document.querySelector('#room-catalogue').innerHTML=roomCatalogueRows(items)||`<p>${t('Для этого состава гостей подходящих категорий нет.','No rooms match this party and view.')}</p>`;document.querySelector('#room-filter-status').textContent=t('Подходящих категорий: ','Matching categories: ')+items.length;}});
document.addEventListener('submit',e=>{if(e.target.id==='newsletter'){e.preventDefault();document.querySelector('#newsletter-status').textContent=t('Спасибо! Это демонстрация: адрес не сохранён, письмо не отправлено.','Thank you! This is a demonstration: your email was not saved and no message was sent.');e.target.reset();}if(e.target.id==='stay-planner'){e.preventDefault();const raw=Object.fromEntries(new FormData(e.target));const errors=validateBooking({...raw,children:'0',name:'Demo Guest',email:'demo@example.com',consent:true});const relevant=['arrival','departure','adults'].filter(k=>errors[k]);const status=e.target.querySelector('#planner-status');e.target.querySelectorAll('input').forEach(input=>input.setAttribute('aria-invalid',String(relevant.includes(input.name))));if(relevant.length){status.textContent=t('Выберите будущий заезд и выезд позже заезда.','Choose today or a future arrival, with check-out after check-in.');e.target.elements[relevant[0]]?.focus();return;}const url=new URL(href('/reservation'),location.origin);for(const key of ['arrival','departure','adults'])url.searchParams.set(key,raw[key]);navigate(url);}if(e.target.id==='booking'){e.preventDefault();submitBooking(e.target);}});
function submitBooking(form){const raw=Object.fromEntries(new FormData(form));raw.consent=form.elements.consent.checked;const errors=validateBooking(raw),messages={arrival:t('Выберите дату не раньше сегодняшней.','Choose today or a later date.'),departure:t('Дата выезда должна быть позже заезда.','Check-out must be after check-in.'),adults:t('Выберите от одного до четырёх взрослых.','Choose one to four adults.'),children:t('Проверьте число детей.','Check the number of children.'),name:t('Введите имя и фамилию.','Enter your full name.'),email:t('Проверьте адрес e-mail.','Check your email address.'),consent:t('Подтвердите условия демонстрации.','Confirm the demonstration terms.'),room:t('Число гостей превышает вместимость категории. Выберите другой номер.','Your party exceeds this room’s capacity. Please choose another room.')};form.querySelectorAll('[data-error]').forEach(el=>{const error=errors[el.dataset.error];el.textContent=error?messages[error]:'';const input=form.elements[el.dataset.error];if(input)input.setAttribute('aria-invalid',String(Boolean(error)));});const result=form.querySelector('#booking-result');if(Object.keys(errors).length){document.querySelector('#announcer').textContent=t('Проверьте отмеченные поля формы.','Please check the highlighted form fields.');result.innerHTML='';form.querySelector('[aria-invalid=true]')?.focus();return;}const summary=buildStaySummary(raw,new URLSearchParams(location.search).get('offer')||''),selectedOffer=offers.find(o=>o.id===summary.offerId);const r=rooms.find(r=>r.id===raw.room),date=value=>new Intl.DateTimeFormat(language==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));result.className='booking-result';result.innerHTML=`<h3>${t('Ваш план поездки','Your stay at a glance')}</h3><p>${esc(raw.name)}, ${date(raw.arrival)} — ${date(raw.departure)}.</p><p>${summary.nights} ${t('ночей','nights')} · ${summary.adults} ${t('взрослых','adults')} · ${summary.children} ${t('детей','children')} · ${r?tr(r.name):t('Категория будет подобрана','Room to be selected')}</p>${selectedOffer?`<p>${t('Выбранная программа','Selected stay')}: ${tr(selectedOffer.name)}</p>`:''}${summary.notes?`<p class="summary-notes">${t('Пожелания','Preferences')}: ${esc(summary.notes)}</p>`:''}<p>${t('Это локальное резюме. Бронирование не создано, данные не отправлены, оплата не списана.','This is a local summary. No reservation was created, nothing was sent and no payment was taken.')}</p>`;result.scrollIntoView({behavior:prefersQuiet()?'instant':'smooth',block:'center'});}
window.addEventListener('popstate',()=>{cancelTransition();if(menu.open)menu.close();readURL();render({focus:true,preserveDraft:true});});
